mapper.select:
SELECT 
FROM TBL_PAYMENT_ORDER p
LEFT JOIN TBL_SUPPLIER s ON p.SUPPLIER_ID = s.SUPPLIER_ID
WHERE p.IS_DELETED = 0

    AND p.PAYMENT_NO LIKE CONCAT('%', #{param.paymentNo}, '%')


    AND p.SUPPLIER_ID = #{param.supplierId}


    AND s.SUPPLIER_NAME LIKE CONCAT('%', #{param.supplierName}, '%')


    AND p.PAYMENT_STATUS = #{param.paymentStatus}


    AND p.PAYMENT_METHOD = #{param.paymentMethod}


    AND p.PAYMENT_DATE >= #{param.paymentDateStart}


    AND p.PAYMENT_DATE <= #{param.paymentDateEnd}


    AND p.PAYMENT_AMOUNT >= #{param.minAmount}


    AND p.PAYMENT_AMOUNT <= #{param.maxAmount}


    AND (p.PAYMENT_NO LIKE CONCAT('%', #{param.keyword}, '%')
         OR s.SUPPLIER_NAME LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY p.CREATE_TIME DESC

mapper.update:
UPDATE TBL_PAYMENT_ORDER
PAYMENT_NO = #{paymentNo}, SUPPLIER_ID = #{supplierId}, PAYMENT_AMOUNT = #{paymentAmount}, WRITE_OFF_AMOUNT = #{writeOffAmount}, REMAINING_AMOUNT = #{remainingAmount}, PAYMENT_STATUS = #{paymentStatus}, PAYMENT_DATE = #{paymentDate}, PAYMENT_METHOD = #{paymentMethod}, BANK_ACCOUNT = #{bankAccount}, RECEIVER_ACCOUNT = #{receiverAccount}, RECEIVER_BANK = #{receiverBank}, SUMMARY = #{summary}, REMARKS = #{remarks}, UPDATE_TIME = #{updateTime}, IS_DELETED = #{isDeleted},
WHERE PAYMENT_ID = #{paymentId}
